func minDuration(left, right time.Duration) time.Duration {
	if left <= 0 {
		return right
	}
	if right <= 0 || left < right {
		return left
	}
	return right
}

func abs(v float64) float64 {
	if v < 0 {
		return -v
	}
	return v
}

