					CostClass:        c.Components.CostClass,
					LatencyMS:        c.Components.LatencyMS,
					SpeedTPS:         c.Components.SpeedTPS,
					Utilization:      c.Components.Utilization,
					SuccessRate:      c.Components.SuccessRate,
					QuotaOK:          c.Components.QuotaOK,
