	model.Family = parsed.Family
	model.Version = append([]int(nil), parsed.Version...)
	model.Tier = parsed.Tier
	model.PreRelease = parsed.PreRelease

	view := modeleligibility.Resolve(model.ID, includeByDefault, string(model.Status), cat)
	model.Power = view.Power
	model.ExactPinOnly = view.ExactPinOnly
	model.AutoRoutable = view.AutoRoutable
	model.ExclusionReason = view.ExclusionReason
	if cat != nil {
		if entry, ok := cat.LookupModel(model.ID); ok {
			model.CostInputPerM = catalogCostInput(entry)
			model.CostOutputPerM = catalogCostOutput(entry)
			model.ContextWindow = entry.ContextWindow
			model.ReasoningLevels = append([]string(nil), entry.ReasoningLevels...)
			model.QuotaPool = entry.EffectiveQuotaPool()
			model.SupportsTools = !entry.NoTools
			model.DeploymentClass = entry.DeploymentClass
			model.ActualCashSpend = billingCreatesCashSpend(model.Billing)
			model.EffectiveCost, model.EffectiveCostSource = effectiveModelCost(entry, model.Billing)
		}
	}
	return model
}

func enrichModel(model KnownModel, includeByDefault bool, cat *modelcatalog.Catalog) KnownModel {
	return EnrichModel(model, includeByDefault, cat)
}

func attachRuntimeSignals(model KnownModel, cache *discoverycache.Cache) KnownModel {
	if cache == nil {
		return model
	}
	sig, ok := runtimesignals.ReadCached(cache, model.Provider)
	if !ok || sig == nil {
		return model
	}
	model.QuotaRemaining = sig.QuotaRemaining
	model.RecentP50Latency = sig.RecentP50Latency
	if !sig.RecordedAt.IsZero() {
		model.HealthFreshnessAt = sig.RecordedAt.UTC()
		model.HealthFreshnessSource = "runtime"
		model.QuotaFreshnessAt = sig.RecordedAt.UTC()
		model.QuotaFreshnessSource = "runtime"
	}
	return model
}

func effectiveProviderIncludeByDefault(providerName string, pc ProviderConfig, cat *modelcatalog.Catalog) bool {
	if pc.IncludeByDefault != nil {
		return *pc.IncludeByDefault
	}
	if cat != nil {
		name := strings.ToLower(strings.TrimSpace(providerName))
		providerType := strings.ToLower(strings.TrimSpace(pc.Type))
		for _, provider := range cat.Providers() {
			catalogName := strings.ToLower(strings.TrimSpace(provider.Name))
			catalogType := strings.ToLower(strings.TrimSpace(provider.Type))
			if name != "" && catalogName == name {
				return provider.IncludeByDefault
			}
			if providerType != "" && (catalogType == providerType || catalogName == providerType) {
				return provider.IncludeByDefault
			}
		}
	}
	switch modelcatalog.BillingModel(strings.TrimSpace(pc.Billing)) {
	case modelcatalog.BillingModelFixed, modelcatalog.BillingModelSubscription:
		return true
	case modelcatalog.BillingModelPerToken:
		return false
	}
	if billing := modelcatalog.BillingForProviderSystem(pc.Type); billing != modelcatalog.BillingModelUnknown {
		return billing == modelcatalog.BillingModelFixed || billing == modelcatalog.BillingModelSubscription
	}
	billing := modelcatalog.BillingForHarness(pc.Type)
	return billing == modelcatalog.BillingModelFixed || billing == modelcatalog.BillingModelSubscription
}

func effectiveProviderBilling(providerName string, pc ProviderConfig, cat *modelcatalog.Catalog) modelcatalog.BillingModel {
	if billing := modelcatalog.BillingModel(strings.TrimSpace(pc.Billing)); billing != modelcatalog.BillingModelUnknown {
		return billing
	}
	if cat != nil {
		name := strings.ToLower(strings.TrimSpace(providerName))
		providerType := strings.ToLower(strings.TrimSpace(pc.Type))
		for _, provider := range cat.Providers() {
			catalogName := strings.ToLower(strings.TrimSpace(provider.Name))
			catalogType := strings.ToLower(strings.TrimSpace(provider.Type))
			if name != "" && catalogName == name {
				return provider.Billing
			}
			if providerType != "" && (catalogType == providerType || catalogName == providerType) {
				return provider.Billing
			}
		}
	}
	if billing := modelcatalog.BillingForProviderSystem(pc.Type); billing != modelcatalog.BillingModelUnknown {
		return billing
	}
	return modelcatalog.BillingForHarness(pc.Type)
}

func providerStatus(cache *discoverycache.Cache, providerName string) ModelStatus {
	if cache == nil {
		return StatusAvailable
	}
	sig, ok := runtimesignals.ReadCached(cache, providerName)
	if !ok || sig == nil {
		return StatusAvailable
	}
	switch sig.Status {
	case runtimesignals.StatusAvailable, runtimesignals.StatusDegraded:
		return StatusAvailable
	case runtimesignals.StatusExhausted:
		return StatusRateLimited
	case runtimesignals.StatusUnknown:
		return StatusUnknown
	default:
		return StatusUnknown
	}
}

func catalogCostInput(entry modelcatalog.ModelEntry) float64 {
	if entry.CostInputPerM != 0 {
		return entry.CostInputPerM
	}
	return entry.CostInputPerMTok
}

func catalogCostOutput(entry modelcatalog.ModelEntry) float64 {
	if entry.CostOutputPerM != 0 {
		return entry.CostOutputPerM
	}
	return entry.CostOutputPerMTok
}

func effectiveModelCost(entry modelcatalog.ModelEntry, billing modelcatalog.BillingModel) (float64, string) {
	cost := catalogCostUSDPer1kTokens(entry)
	if cost == 0 {
		return 0, "unknown"
	}
	if billing == modelcatalog.BillingModelSubscription {
		return cost, "subscription_shadow"
	}
	return cost, "catalog"
}

func billingCreatesCashSpend(billing modelcatalog.BillingModel) bool {
	return billing == modelcatalog.BillingModelPerToken
}

func catalogCostUSDPer1kTokens(entry modelcatalog.ModelEntry) float64 {
	input := entry.CostInputPerM
	if input == 0 {
		input = entry.CostInputPerMTok
	}
	output := entry.CostOutputPerM
	if output == 0 {
		output = entry.CostOutputPerMTok
	}
	switch {
	case input > 0 && output > 0:
		return ((input + output) / 2) / 1000
	case input > 0:
		return input / 1000
	case output > 0:
		return output / 1000
	default:
		return 0
	}
}

package session

import (
	"encoding/json"
	"fmt"
	"io"
	"strings"

	agent "github.com/easel/fizeau/internal/core"
)

// Replay reads a session log and renders a human-readable conversation.
func Replay(path string, w io.Writer) error {
	events, err := ReadEvents(path)
	if err != nil {
		return fmt.Errorf("replay: %w", err)
	}

	for _, e := range events {
		switch e.Type {
		case agent.EventLLMRequest:
			var data LLMRequestData
			if err := json.Unmarshal(e.Data, &data); err != nil {
				continue
			}
			fmt.Fprintf(w, "\n[LLM Request] (%d messages, %d tools)\n", len(data.Messages), len(data.Tools))
			for _, m := range data.Messages {
				switch m.Role {
				case agent.RoleSystem:
					fmt.Fprintf(w, "  [system] %s\n", m.Content)
				case agent.RoleUser:
					fmt.Fprintf(w, "  [user] %s\n", m.Content)
				case agent.RoleAssistant:
					if m.Content != "" {
						fmt.Fprintf(w, "  [assistant] %s\n", m.Content)
					}
					for _, tc := range m.ToolCalls {
						fmt.Fprintf(w, "  [assistant tool_call] %s(%s)\n", tc.Name, compactJSON(tc.Arguments))
					}
				case agent.RoleTool:
					content := m.Content
					if len(content) > 200 {
						content = content[:200] + "...[truncated]"
					}
					fmt.Fprintf(w, "  [tool result] %s\n", strings.ReplaceAll(content, "\n", "\n              "))
				}
			}

		case agent.EventSessionStart:
			var data SessionStartData
			if err := json.Unmarshal(e.Data, &data); err != nil {
				continue
			}
			fmt.Fprintf(w, "=== Session %s ===\n", e.SessionID)
			fmt.Fprintf(w, "Time: %s\n", e.Timestamp.Format("2006-01-02 15:04:05 UTC"))
			fmt.Fprintf(w, "Provider: %s | Model: %s\n", data.Provider, data.Model)
			if data.SelectedEndpoint != "" {
				fmt.Fprintf(w, "Selected endpoint: %s\n", data.SelectedEndpoint)
			}
			if data.SelectedServerInstance != "" {
				fmt.Fprintf(w, "Selected server instance: %s\n", data.SelectedServerInstance)
			}
			if data.Sticky.KeyPresent || data.Sticky.Assignment != "" || data.Sticky.Reason != "" {
				fmt.Fprintf(w, "Sticky: key=%s assignment=%s",
					routingStickyLabel(data.Sticky.KeyPresent),
					labelOrUnknown(data.Sticky.Assignment))
				if data.Sticky.Reason != "" {
					fmt.Fprintf(w, " reason=%s", data.Sticky.Reason)
				}
				if data.Sticky.Bonus != 0 {
					fmt.Fprintf(w, " bonus=%.2f", data.Sticky.Bonus)
				}
				fmt.Fprintln(w)
			}
			if data.Utilization.Source != "" || data.Utilization.Freshness != "" ||
				data.Utilization.ActiveRequests != nil || data.Utilization.QueuedRequests != nil ||
				data.Utilization.MaxConcurrency != nil || data.Utilization.CachePressure != nil {
				fmt.Fprintf(w, "Utilization: source=%s freshness=%s",
					labelOrUnknown(data.Utilization.Source),
					labelOrUnknown(data.Utilization.Freshness))
				if data.Utilization.ActiveRequests != nil {
					fmt.Fprintf(w, " active=%d", *data.Utilization.ActiveRequests)
				}
				if data.Utilization.QueuedRequests != nil {
					fmt.Fprintf(w, " queued=%d", *data.Utilization.QueuedRequests)
				}
				if data.Utilization.MaxConcurrency != nil {
					fmt.Fprintf(w, " max=%d", *data.Utilization.MaxConcurrency)
				}
				if data.Utilization.CachePressure != nil {
					fmt.Fprintf(w, " cache_pressure=%.2f", *data.Utilization.CachePressure)
				}
				fmt.Fprintln(w)
			}
			fmt.Fprintf(w, "Max iterations: %d | Work dir: %s\n", data.MaxIterations, data.WorkDir)
			if data.SystemPrompt != "" {
				fmt.Fprintf(w, "\n[System]\n%s\n", data.SystemPrompt)
			}
			fmt.Fprintf(w, "\n[User]\n%s\n", data.Prompt)

		case agent.EventLLMResponse:
			var data LLMResponseData
			if err := json.Unmarshal(e.Data, &data); err != nil {
				continue
			}
			fmt.Fprintf(w, "\n[Assistant] (%dms, %d in / %d out tokens",
				data.LatencyMs, data.Usage.Input, data.Usage.Output)
			if data.CostUSD > 0 {
				fmt.Fprintf(w, ", $%.4f", data.CostUSD)
			}
			fmt.Fprintf(w, ")\n")
			if data.Content != "" {
				fmt.Fprintf(w, "%s\n", data.Content)
			}
			if len(data.ToolCalls) > 0 {
				fmt.Fprintf(w, "[%d tool call(s)]\n", len(data.ToolCalls))
			}

		case agent.EventToolCall:
			var data ToolCallData
			if err := json.Unmarshal(e.Data, &data); err != nil {
				continue
			}
			fmt.Fprintf(w, "\n  > %s (%dms)\n", data.Tool, data.DurationMs)
			fmt.Fprintf(w, "    Input:  %s\n", compactJSON(data.Input))
			output := data.Output
			if len(output) > 200 {
				output = output[:200] + "...[truncated]"
			}
			fmt.Fprintf(w, "    Output: %s\n", strings.ReplaceAll(output, "\n", "\n            "))
			if data.Error != "" {
				fmt.Fprintf(w, "    Error:  %s\n", data.Error)
			}

		case agent.EventSessionEnd:
			var data SessionEndData
			if err := json.Unmarshal(e.Data, &data); err != nil {
				continue
			}
			fmt.Fprintf(w, "\n=== End (%s) ===\n", data.Status)
			if data.Model != "" {
				fmt.Fprintf(w, "Model: %s\n", data.Model)
			}
			if data.SelectedEndpoint != "" {
				fmt.Fprintf(w, "Selected endpoint: %s\n", data.SelectedEndpoint)
			}
			if data.SelectedServerInstance != "" {
				fmt.Fprintf(w, "Selected server instance: %s\n", data.SelectedServerInstance)
			}
			fmt.Fprintf(w, "Duration: %dms | Tokens: %d in / %d out",
				data.DurationMs, data.Tokens.Input, data.Tokens.Output)
			if data.CostUSD == nil || *data.CostUSD < 0 {
				fmt.Fprintf(w, " | Cost: unknown")
			} else if *data.CostUSD > 0 {
				fmt.Fprintf(w, " | Cost: $%.4f", *data.CostUSD)
			} else {
				fmt.Fprintf(w, " | Cost: $0 (local)")
			}
			fmt.Fprintln(w)
			if len(data.Metadata) > 0 {
				fmt.Fprintf(w, "Metadata:")
				for k, v := range data.Metadata {
					fmt.Fprintf(w, " %s=%s", k, v)
				}
				fmt.Fprintln(w)
			}
			if data.Error != "" {
				fmt.Fprintf(w, "Error: %s\n", data.Error)
			}
		}
	}
	return nil
}

func routingStickyLabel(present bool) string {
	if present {
		return "present"
	}
	return "absent"
}

func labelOrUnknown(v string) string {
	if v == "" {
		return "unknown"
	}
	return v
}

func compactJSON(raw json.RawMessage) string {
	var v any
	if json.Unmarshal(raw, &v) != nil {
		return string(raw)
	}
	data, _ := json.Marshal(v)
	return string(data)
}

package fizeau_test

import (
	"context"
	"encoding/json"
	"testing"
	"time"

	fizeau "github.com/easel/fizeau"
	"github.com/easel/fizeau/internal/harnesses"
)

func TestDrainExecute_DecodesTypedResult(t *testing.T) {
	ch := make(chan fizeau.ServiceEvent, 7)
	ch <- serviceEvent(t, fizeau.ServiceEventTypeRoutingDecision, 0, map[string]any{
		"harness":         "fiz",
		"provider":        "fake",
		"server_instance": "fake-instance",
		"model":           "fake-model",
		"reason":          "test route",
		"session_id":      "svc-test",
	})
	ch <- serviceEvent(t, fizeau.ServiceEventTypeTextDelta, 1, map[string]any{"text": "APPROVE\n"})
	ch <- serviceEvent(t, fizeau.ServiceEventTypeToolCall, 2, map[string]any{
		"id": "call-1", "name": "read", "input": map[string]any{"path": "README.md"},
	})
	ch <- serviceEvent(t, fizeau.ServiceEventTypeToolResult, 3, map[string]any{
		"id": "call-1", "output": "contents", "duration_ms": 12,
	})
	ch <- serviceEvent(t, fizeau.ServiceEventTypeCompaction, 4, map[string]any{
		"messages_before": 9, "messages_after": 4, "tokens_freed": 500,
	})
	ch <- serviceEvent(t, fizeau.ServiceEventTypeStall, 5, map[string]any{
		"reason": "read_only_tools_exceeded", "count": 25,
	})
	ch <- serviceEvent(t, fizeau.ServiceEventTypeFinal, 6, map[string]any{
		"status":      "success",
		"exit_code":   0,
		"final_text":  "APPROVE\nLooks good.",
		"duration_ms": 123,
		"usage": map[string]any{
			"input_tokens": 10, "output_tokens": 5, "total_tokens": 15, "source": "native_stream", "fresh": true,
		},
		"warnings": []map[string]any{
			{"code": "usage_source_disagreement", "message": "selected by precedence"},
		},
		"cost_usd":         0.001,
		"session_log_path": "/tmp/session.jsonl",
		"routing_actual": map[string]any{
			"harness": "fiz", "provider": "fake", "server_instance": "fake-instance", "model": "fake-model",
		},
	})
	close(ch)

	result, err := fizeau.DrainExecute(context.Background(), ch)
	if err != nil {
		t.Fatalf("DrainExecute: %v", err)
	}
	if result.FinalStatus != "success" {
		t.Fatalf("FinalStatus: got %q", result.FinalStatus)
	}
	if result.FinalText != "APPROVE\nLooks good." {
		t.Fatalf("FinalText: got %q", result.FinalText)
	}
	if result.Usage == nil || result.Usage.TotalTokens == nil || *result.Usage.TotalTokens != 15 {
		t.Fatalf("Usage: got %#v", result.Usage)
	}
	if result.Usage.Source != "native_stream" || result.Usage.Fresh == nil || !*result.Usage.Fresh {
		t.Fatalf("Usage metadata: got %#v", result.Usage)
	}
	if len(result.Warnings) != 1 || result.Warnings[0].Code != "usage_source_disagreement" {
		t.Fatalf("Warnings: got %#v", result.Warnings)
	}
	if len(result.ToolCalls) != 1 || result.ToolCalls[0].Name != "read" {
		t.Fatalf("ToolCalls: got %#v", result.ToolCalls)
	}
	if len(result.ToolResults) != 1 || result.ToolResults[0].Output != "contents" {
		t.Fatalf("ToolResults: got %#v", result.ToolResults)
	}
	if result.RoutingDecision == nil || result.RoutingDecision.SessionID != "svc-test" {
		t.Fatalf("RoutingDecision: got %#v", result.RoutingDecision)
	}
	if result.RoutingDecision.ServerInstance != "fake-instance" {
		t.Fatalf("RoutingDecision.ServerInstance: got %q", result.RoutingDecision.ServerInstance)
	}
	if result.RoutingActual == nil || result.RoutingActual.Provider != "fake" {
		t.Fatalf("RoutingActual: got %#v", result.RoutingActual)
	}
	if result.RoutingActual.ServerInstance != "fake-instance" {
		t.Fatalf("RoutingActual.ServerInstance: got %q", result.RoutingActual.ServerInstance)
	}
	if result.SessionLogPath != "/tmp/session.jsonl" {
		t.Fatalf("SessionLogPath: got %q", result.SessionLogPath)
	}
	if len(result.Compactions) != 1 || result.Compactions[0].TokensFreed != 500 {
		t.Fatalf("Compactions: got %#v", result.Compactions)
	}
	if len(result.Stalls) != 1 || result.Stalls[0].Count != 25 {
		t.Fatalf("Stalls: got %#v", result.Stalls)
	}
}

func serviceEvent(t *testing.T, typ string, seq int64, payload any) fizeau.ServiceEvent {
	t.Helper()
	raw, err := json.Marshal(payload)
	if err != nil {
		t.Fatalf("marshal payload: %v", err)
	}
	return fizeau.ServiceEvent{
		Type:     harnesses.EventType(typ),
		Sequence: seq,
		Time:     time.Unix(seq, 0).UTC(),
		Metadata: map[string]string{"bead_id": "test"},
		Data:     raw,
	}
}

